param([string]$Id)
$ErrorActionPreference='Stop'
if($Id -cnotmatch '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'){throw 'Use the original recovery ID'}
$session=New-PSSession -ComputerName domain02.cormierconsulting.com
try{Invoke-Command -Session $session -ArgumentList $Id -ScriptBlock {
 param($id);$ErrorActionPreference='Stop';$root='C:\ProgramData\CormierDnsManager';. (Join-Path $root 'RecoveryChannel\windows-dns-credential-recovery.ps1');$paths=Get-DnsRecoveryPaths $root $id;$payload=Get-DnsRecoveryPayload $paths $id
 $beforeBytes=[Convert]::FromBase64String($payload.before);$before=[Text.Encoding]::UTF8.GetString($beforeBytes)|ConvertFrom-Json;$target=$payload.target|ConvertFrom-Json;$receipt=Get-Content -LiteralPath $paths.receipt -Raw|ConvertFrom-Json;$valid=$false;try{$null=Assert-DnsRecoveryConfiguration ([Text.Encoding]::UTF8.GetString($beforeBytes)) $target.clusters[0].cluster.'certificate-authority-data';$valid=$true}catch{}
 @{id=$id;status=$receipt.status;writeIntent=[bool]$receipt.writeIntent;leasePresent=(Test-Path -LiteralPath $paths.lease);originalConfigurationValid=$valid;tokenPreserved=($before.users[0].user.token -ceq $target.users[0].user.token);caPreserved=($before.clusters[0].cluster.'certificate-authority-data' -ceq $target.clusters[0].cluster.'certificate-authority-data');serverPreserved=($before.clusters[0].cluster.server -ceq $target.clusters[0].cluster.server);tlsNamePreserved=($before.clusters[0].cluster.'tls-server-name' -ceq $target.clusters[0].cluster.'tls-server-name');contextPreserved=($before.'current-context' -ceq $target.'current-context' -and $before.contexts[0].context.cluster -ceq $target.contexts[0].context.cluster -and $before.contexts[0].context.user -ceq $target.contexts[0].context.user -and $before.contexts[0].context.namespace -ceq $target.contexts[0].context.namespace);beforeTopLevelOrder=@($before.PSObject.Properties.Name);targetTopLevelOrder=@($target.PSObject.Properties.Name);currentMatchesAppliedBytes=(Test-DnsRecoveryBytes ([IO.File]::ReadAllBytes($paths.credential)) ([Convert]::FromBase64String($payload.targetBytes)));credentialValuesDisplayed=$false}|ConvertTo-Json -Depth 5
 }}finally{Remove-PSSession $session}
